let __v_258 = pyrt::literals::decode("{\"$dict\":[[\"africa\",{\"$dict\":[[\"river\",\"The Nile, at about 6,650 km - the longest river in Africa and usually counted the longest in the world. The Congo carries far more water.\"],[\"mountain\",\"Kilimanjaro, at 5,895 m, in Tanzania - the highest mountain in Africa, and a walk-up rather than a climb, though the altitude is the hard part.\"],[\"desert\",\"The Sahara, at about 9 million square km - the largest hot desert in the world, roughly the size of the United States.\"]]}],[\"europe\",{\"$dict\":[[\"river\",\"The Volga, at about 3,530 km, running through Russia to the Caspian Sea. The Danube is second, at about 2,850 km, and passes through ten countries.\"],[\"mountain\",\"Mount Elbrus, at 5,642 m, in the Russian Caucasus - the highest in Europe and one of the seven summits.\"]]}],[\"asia\",{\"$dict\":[[\"river\",\"The Yangtze, at about 6,300 km - the longest river wholly in Asia. Russia's Ob and Yenisei are longer but are only partly in Asia.\"],[\"mountain\",\"Mount Everest, at 8,849 m - the highest in Asia and in the world.\"],[\"desert\",\"The Arabian Desert, at about 2.3 million square km. The Gobi is the biggest cold desert, and the Sahara is the biggest hot one - it is in Africa.\"]]}],[\"north america\",{\"$dict\":[[\"river\",\"The Missouri-Mississippi, at about 6,275 km from source to the Gulf of Mexico. The Mississippi alone is about 3,770 km.\"],[\"mountain\",\"Denali, at 6,190 m, in Alaska. Mount Logan in Canada is second, at 5,959 m.\"],[\"desert\",\"The Great Basin Desert, at about 490,000 square km, in the western United States. The Chihuahuan, shared with Mexico, is the biggest hot one.\"]]}],[\"south america\",{\"$dict\":[[\"river\",\"The Amazon, at about 6,400 km, and far and away the biggest by water - about a fifth of all the river water on Earth.\"],[\"mountain\",\"Aconcagua, at 6,961 m, in Argentina - the highest mountain outside Asia.\"],[\"desert\",\"The Patagonian Desert, at about 670,000 square km. The Atacama is the driest desert, not the biggest.\"]]}],[\"oceania\",{\"$dict\":[[\"river\",\"The Murray, at about 2,508 km, with the Darling - the longest river system in Oceania, running through Australia.\"],[\"mountain\",\"Puncak Jaya, at 4,884 m, in Indonesian Papua. Australia's own highest is Mount Kosciuszko, at 2,228 m.\"],[\"desert\",\"The Great Victoria Desert, at about 348,000 square km, in Australia.\"]]}],[\"uk\",{\"$dict\":[[\"river\",\"The Severn, at about 354 km (220 miles), is the longest river in the UK, rising in Wales and reaching the sea past Bristol. The Thames is second at about 346 km.\"],[\"lake\",\"Lough Neagh in Northern Ireland is the largest lake in the UK by area, at about 383 square km. Loch Ness holds the most water, about 7.5 cubic km.\"],[\"deep lake\",\"Loch Morar is the deepest lake in Britain, at 310 metres, deeper than the North Sea is in most places. Loch Ness is 230 metres but holds far more water.\"],[\"desert\",\"There are no deserts in the UK: nowhere here is dry enough to count as one. The closest thing is a dune system such as the Sefton coast or Braunton Burrows.\"]]}],[\"britain\",{\"$dict\":[[\"river\",\"The Severn, at about 354 km, is the longest river in Britain, with the Thames second at about 346 km and the Trent third.\"],[\"lake\",\"Loch Lomond, at about 71 square km, is the largest lake in Britain by area. Windermere is the largest in England at about 14.7 square km.\"],[\"deep lake\",\"Loch Morar, at 310 metres, is the deepest lake in Britain. Loch Ness is second at 230 metres and holds more water than all the lakes of England and Wales together.\"]]}],[\"england\",{\"$dict\":[[\"river\",\"The Severn, at about 354 km (220 miles), is the longest river in England, though it rises in Wales. The Thames is second at about 346 km, and the longest river wholly inside England.\"],[\"lake\",\"Windermere is the largest lake in England, about 14.7 square km and 18 km long. Wastwater is the deepest, at 74 metres, and was voted Britain's favourite view.\"],[\"deep lake\",\"Wastwater in the Lake District is the deepest lake in England, at 74 metres, and the coldest: it is a long narrow trench under the Screes.\"]]}],[\"scotland\",{\"$dict\":[[\"river\",\"The Tay, at about 188 km (117 miles), is the longest river in Scotland and the biggest by water, carrying more than the Thames and the Severn together.\"],[\"lake\",\"Loch Lomond is the largest lake in Scotland by area, about 71 square km. Loch Ness is bigger by volume and holds more fresh water than all of England and Wales put together.\"],[\"deep lake\",\"Loch Morar in the west Highlands is the deepest lake in Scotland and in Britain, at 310 metres.\"]]}],[\"wales\",{\"$dict\":[[\"river\",\"The Severn rises in the Welsh hills and is the longest river to run through Wales, at about 354 km. The longest river wholly inside Wales is the Tywi, at about 120 km.\"],[\"lake\",\"Llyn Tegid, also called Bala Lake, is the largest natural lake in Wales at about 4.8 square km, and it has its own species of whitefish, the gwyniad.\"]]}],[\"northern ireland\",{\"$dict\":[[\"river\",\"The Bann, at about 129 km, is the longest river in Northern Ireland: the Upper Bann feeds Lough Neagh and the Lower Bann carries it to the sea at Coleraine.\"],[\"lake\",\"Lough Neagh is the largest lake in Northern Ireland and in the British Isles, at about 383 square km, and it supplies much of Belfast's drinking water.\"]]}],[\"ireland\",{\"$dict\":[[\"river\",\"The Shannon, at about 360 km, is the longest river in Ireland, running from the Cavan hills south to Limerick and the Atlantic.\"],[\"lake\",\"Lough Neagh, in Northern Ireland, is the largest lake on the island of Ireland at about 383 square km. The largest in the Republic is Lough Corrib, about 176 square km, in County Galway.\"]]}],[\"antarctica\",{\"$dict\":[[\"river\",\"There are no real rivers: the Onyx is a seasonal meltwater stream about 30 km long, and it is the longest in Antarctica.\"],[\"mountain\",\"Vinson Massif, at 4,892 m - the highest in Antarctica, and the coldest of the seven summits.\"],[\"desert\",\"Antarctica is itself the largest desert on Earth, at about 14 million square km: a desert is about how little it rains, not about sand.\"]]}]]}")?;
