let __v_454 = pyrt::literals::decode("{\"$tuple\":[{\"$tuple\":[\"nile\",\"The Nile runs about 6,650 km from its source to the Mediterranean, which makes it the longest river in Africa and usually the longest in the world - with the Amazon a close second and carrying far more water.\"]},{\"$tuple\":[\"amazon\",\"The Amazon runs about 6,400 km from its source in the Peruvian Andes to the Atlantic, and it is the biggest river in the world by water - about a fifth of all the river water on Earth.\"]},{\"$tuple\":[\"mississippi\",\"The Mississippi is about 3,770 km from Minnesota to the Gulf of Mexico, or about 6,275 km if you count the Missouri from its source, which is how it is usually measured.\"]},{\"$tuple\":[\"missouri\",\"The Missouri is about 3,767 km, from Montana to where it joins the Mississippi near St Louis - the longest river in North America on its own.\"]},{\"$tuple\":[\"danube\",\"The Danube runs about 2,850 km from Germany's Black Forest to the Black Sea, through ten countries - more than any other river in the world.\"]},{\"$tuple\":[\"volga\",\"The Volga runs about 3,530 km through Russia to the Caspian Sea, the longest river in Europe.\"]},{\"$tuple\":[\"yangtze\",\"The Yangtze runs about 6,300 km across China to the sea at Shanghai, the longest river in Asia.\"]},{\"$tuple\":[\"congo\",\"The Congo runs about 4,700 km, the deepest river in the world and second only to the Amazon by water.\"]},{\"$tuple\":[\"rhine\",\"The Rhine runs about 1,230 km from the Swiss Alps to the North Sea at Rotterdam, and it is the busiest freight river in Europe.\"]},{\"$tuple\":[\"seine\",\"The Seine runs about 775 km, from Burgundy through Paris to the sea at Le Havre.\"]},{\"$tuple\":[\"thames\",\"The Thames runs about 346 km, from the Cotswolds through London to the Thames Estuary.\"]},{\"$tuple\":[\"loire\",\"The Loire runs about 1,006 km, the longest river in France, from the Massif Central to the Atlantic at Saint-Nazaire.\"]},{\"$tuple\":[\"po\",\"The Po runs about 652 km across northern Italy to the Adriatic, the longest river in Italy.\"]},{\"$tuple\":[\"tagus\",\"The Tagus runs about 1,007 km from Spain through Portugal to Lisbon and the Atlantic, the longest river on the Iberian peninsula.\"]},{\"$tuple\":[\"elbe\",\"The Elbe runs about 1,094 km from the Czech Republic through Germany to the North Sea at Hamburg.\"]},{\"$tuple\":[\"oder\",\"The Oder runs about 840 km from the Czech Republic to the Baltic, most of it along the border between Germany and Poland.\"]},{\"$tuple\":[\"ganges\",\"The Ganges runs about 2,525 km from the Himalayas to the Bay of Bengal, and with its delta it is one of the most populous river basins in the world.\"]},{\"$tuple\":[\"indus\",\"The Indus runs about 3,180 km from Tibet through Pakistan to the Arabian Sea, and the civilisation along it was one of the first cities anywhere.\"]},{\"$tuple\":[\"mekong\",\"The Mekong runs about 4,350 km from the Tibetan plateau through China, Laos, Thailand, Cambodia and Vietnam to the South China Sea.\"]},{\"$tuple\":[\"yellow river\",\"The Yellow River runs about 5,464 km across northern China, the second longest in the country after the Yangtze.\"]},{\"$tuple\":[\"ob\",\"The Ob runs about 3,650 km across Siberia to the Arctic Ocean, or about 5,410 km with its main tributary, the Irtysh.\"]},{\"$tuple\":[\"yenisei\",\"The Yenisei runs about 3,487 km across Siberia to the Arctic, and with its headwaters it is one of the longest river systems in the world.\"]},{\"$tuple\":[\"murray\",\"The Murray runs about 2,508 km through Australia to the sea in South Australia, and with the Darling it is the longest river system in the country.\"]},{\"$tuple\":[\"darling\",\"The Darling runs about 1,472 km through New South Wales and Queensland, the longest single river in Australia.\"]},{\"$tuple\":[\"colorado\",\"The Colorado runs about 2,330 km from the Rocky Mountains to the Gulf of California, through the Grand Canyon on the way.\"]},{\"$tuple\":[\"rio grande\",\"The Rio Grande runs about 3,051 km from Colorado to the Gulf of Mexico, and it forms the border between Texas and Mexico.\"]},{\"$tuple\":[\"parana\",\"The Parana runs about 4,880 km through Brazil, Paraguay and Argentina to the Rio de la Plata, second in South America only to the Amazon.\"]},{\"$tuple\":[\"orinoco\",\"The Orinoco runs about 2,140 km through Venezuela to the Atlantic, and it links to the Amazon through a natural channel, the Casiquiare.\"]},{\"$tuple\":[\"niger\",\"The Niger runs about 4,200 km in a great curve through West Africa to the Gulf of Guinea, the longest river in the region.\"]},{\"$tuple\":[\"zambezi\",\"The Zambezi runs about 2,574 km through southern Africa to the Indian Ocean, and Victoria Falls is on it.\"]},{\"$tuple\":[\"amur\",\"The Amur runs about 2,824 km along the border between Russia and China to the Pacific, or about 4,444 km with its headwaters.\"]},{\"$tuple\":[\"lena\",\"The Lena runs about 4,400 km across Siberia to the Arctic Ocean, and it freezes solid for months each winter.\"]},{\"$tuple\":[\"irrawaddy\",\"The Irrawaddy runs about 2,170 km through Myanmar to the sea, the country's main river for transport and rice.\"]},{\"$tuple\":[\"euphrates\",\"The Euphrates runs about 2,800 km from Turkey through Syria and Iraq to the Shatt al-Arab, where it joins the Tigris.\"]},{\"$tuple\":[\"tigris\",\"The Tigris runs about 1,850 km from Turkey through Iraq to the Shatt al-Arab, and the land between it and the Euphrates is ancient Mesopotamia.\"]}]}")?;
